it('should record multiple chapters when setCount jumps across thresholds', async () => {
  const { result } = renderHook(() => useGameState({
    card: { id: 'saga1', chapters: 3, loreCount: 0 },
    game: { loreCount: 0 }
  }));
  const { setCount } = result.current;

  await setCount(2);
  expect(result.current.card.triggeredChapters).toEqual([1, 2]);
});

it('should record a single chapter when adjustCount steps across threshold', async () => {
  const { result } = renderHook(() => useGameState({
    card: { id: 'saga2', chapters: 3, loreCount: 0 },
    game: { loreCount: 0 }
  }));
  const { adjustCount } = result.current;

  await adjustCount(1);
  expect(result.current.card.triggeredChapters).toEqual([1]);
});

it('should not untrigger chapters when count is decreased', async () => {
  const { result } = renderHook(() => useGameState({
    card: { id: 'saga3', chapters: 3, loreCount: 2 },
    game: { loreCount: 2 }
  }));
  const { adjustCount } = result.current;

  await adjustCount(-1);
  expect(result.current.card.triggeredChapters).toEqual([1, 2]);
});

